local CatHomeCountDownNode = Class('CatHomeCountDownNode')

---@type CatHouseMgr
local CatHouseMgr = import('Game.CatHouse.CatHouseMgr')
local Hatching = CatHouseMgr.ConstantsCatHouse.CatStatus.Hatching
local CatHouseTimeChange = Constants.EventNames.CatHouseTimeChange
local CatHouseSwitchEntryAnimation = Constants.EventNames.CatHouseSwitchEntryAnimation
local GetTimeHMS2 = CfUtils.GetTimeHMS2

function CatHomeCountDownNode:__init()
    self.isHatchComplete = false
end

