function CatHomeCountDownNode:UpdateListener(focus)
    if focus then
        self:AddListener()
    else
        self:RemoveListener()
    end
end

function CatHomeCountDownNode:AddListener()
    if self.__EventCatHouseTimeChangeAction then return end
    self.__EventCatHouseTimeChangeAction = Events.AddListener(CatHouseTimeChange, Bind(self, self.OnEventCatHouseTimeChangeAction))
end

function CatHomeCountDownNode:RemoveListener()
    if self.__EventCatHouseTimeChangeAction then
        Events.RemoveListener(CatHouseTimeChange, self.__EventCatHouseTimeChangeAction)
        self.__EventCatHouseTimeChangeAction = nil
    end
end

function CatHomeCountDownNode:OnEventCatHouseTimeChangeAction()
    ---@type CatHouseComponent
    local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)
    local cdData = component:GetCatCDData()
    if cdData == nil or next(cdData) == nil then
        return
    end
    local seconds = 9999999999
    for i, v in pairs(cdData) do
        local tempSeconds = v[Hatching]
        if tempSeconds and tempSeconds >= 0 then
            seconds = math.min(seconds, tempSeconds)
            if seconds == 0 then break end
        end
    end
    local isHatchComplete = seconds == 0
    if isHatchComplete ~= self.isHatchComplete then
        self.isHatchComplete = isHatchComplete
        Events.Broadcast(CatHouseSwitchEntryAnimation, isHatchComplete)
    end

end

return CatHomeCountDownNode